package com.workintech.s18d1.entity;import jakarta.persistence.*;import lombok.AllArgsConstructor;import lombok.Data;import lombok.NoArgsConstructor;@Entity@Table(name = "burger")@Data@AllArgsConstructor@NoArgsConstructorpublic class Burger {    @Id    @GeneratedValue(strategy = GenerationType.IDENTITY)    private Long id;    private String name;    private double price;    private boolean isVegan;    private  BreadType breadType;    private String contents;}